17	
18	    private CustomerCode() {
19	    }
20	
21	    /**
22	     * Format {@code city}, {@code lastName} and {@code sequence} into a customer code, e.g.
23	     * {@code format("Springfield", "Smithers", 7)} yields {@code "SPR-SMI-0007"}.
24	     */
25	    static String format(String city, String lastName, int sequence) {
26	        return String.format("%s-%s-%04d", prefix(city), prefix(lastName), sequence);
27	    }
28	
29	    /** The upper-cased first three letters of {@code value} (fewer when it is shorter). */
30	    private static String prefix(String value) {
31	        return value.substring(0, Math.min(PREFIX_LENGTH, value.length())).toUpperCase(Locale.ROOT);
