2	
3	import java.util.Locale;
4	
5	import org.springframework.samples.petclinic.model.Owner;
6	
7	/**
8	 * The single definition of two owners being in the same city, compared case-insensitively
9	 * (leading and trailing whitespace ignored). Provides the membership test used to count how
10	 * many existing owners already live in a new owner's city.
11	 *
12	 * @see AssignOwnerCustomerCode derives the per-city sequence of the customer code.
13	 */
14	final class SameCity {
15	
16	    private SameCity() {
17	    }
18	
19	    /** Whether {@code owner} is in {@code city}. */
20	    static boolean matches(Owner owner, String city) {
21	        return normalize(owner.getCity()).equals(normalize(city));
22	    }
23	
24	    /** How many of {@code owners} are in {@code city}. */
25	    static int count(Iterable<Owner> owners, String city) {
26	        int inCity = 0;
27	        for (Owner owner : owners) {
28	            if (matches(owner, city)) {
29	                inCity++;
30	            }
31	        }
32	        return inCity;
33	    }
34	
35	    /** A city name trimmed and lower-cased, so comparison is case-insensitive. */
36	    private static String normalize(String value) {
37	        return value == null ? "" : value.strip().toLowerCase(Locale.ROOT);
38	    }
39	}
